using UnityEngine;

namespace TarkovSDK
{
    // Spawns bots when a player fires a trigger id (CustomMapLoader's own; the game only spawns by waves and boss
    // spawns from the server). The bots come at this object's children (or the object itself, with no children), as
    // the game spawns any bot: their profiles are generated by the server for the role and difficulty, and they join
    // the nearest bot zone. Editor-only data on an EditorOnly object: Build Map exports it to sdk_export.json and the
    // client plugin spawns them (on the host in Fika co-op).
    [AddComponentMenu("Tarkov SDK/Spawn Bots")]
    public class TarkovSpawnBots : MonoBehaviour
    {
        // the game's WildSpawnType, by name (the common ones; SPT names its PMCs pmcBEAR / pmcUSEC)
        public enum Role
        {
            [Tooltip("Scav.")]
            assault,
            [Tooltip("Sniper scav.")]
            marksman,
            [Tooltip("BEAR PMC (SPT).")]
            pmcBEAR,
            [Tooltip("USEC PMC (SPT).")]
            pmcUSEC,
            [Tooltip("Raider (Labs, Reserve).")]
            pmcBot,
            [Tooltip("Rogue (Lighthouse).")]
            exUsec,
            [Tooltip("Cultist.")]
            sectantWarrior,
            [Tooltip("Cultist priest.")]
            sectantPriest,
            [Tooltip("Scav that's hostile to player scavs.")]
            cursedAssault,
            [Tooltip("Factory's Tagilla.")]
            bossTagilla,
            [Tooltip("Interchange's Killa.")]
            bossKilla,
            [Tooltip("Customs' Reshala.")]
            bossBully,
            [Tooltip("Shoreline's Sanitar.")]
            bossSanitar,
            [Tooltip("Woods' Shturman.")]
            bossKojaniy,
            [Tooltip("Reserve's Glukhar.")]
            bossGluhar,
            [Tooltip("Streets' Kaban.")]
            bossBoar,
            [Tooltip("Lighthouse's Knight.")]
            bossKnight,
            [Tooltip("Ground Zero / Streets' Kollontay.")]
            bossKolontay,
            [Tooltip("Labyrinth's Partisan.")]
            bossPartisan,
        }

        // the game's BotDifficulty
        public enum Difficulty { easy, normal, hard, impossible }

        [Tooltip("Spawn them when a player fires this trigger id (a zone or a switch; connect one in Triggers & Sounds).")]
        public string TriggerId = "";

        [Tooltip("Only once per raid.")]
        public bool Once = true;

        [Tooltip("The chance it happens each time the trigger fires.")]
        [Range(0f, 1f)]
        public float Chance = 1f;

        public Role BotRole = Role.assault;

        public Difficulty BotDifficulty = Difficulty.normal;

        [Tooltip("How many bots. They share the spawn points (children of this object) in turn.")]
        [Min(1)]
        public int Count = 2;

        [Tooltip("Spawn them as one group (they fight together and follow a leader).")]
        public bool AsGroup = true;

        [Tooltip("Seconds from the trigger to the spawn.")]
        [Min(0f)]
        public float Delay;

        [Tooltip("Don't spawn while the map already has this many bots alive (0: no limit). The map's own wave limit (base.json BotMax) doesn't apply to these.")]
        [Min(0)]
        public int MaxAliveBots = 0;
    }
}
